changeSet.sql:
CREATE TABLE IF NOT EXISTS "user".scoring_usage (
    id            UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    user_in       TEXT,
    package_id    UUID,
    scoring_type  TEXT,          -- HESAP | KATM | PAYMENT
    scoring_ref   TEXT,          -- integration scoring id (izlash uchun)
    created_at    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_scoring_usage_pkg
    ON "user".scoring_usage (package_id, scoring_type);
